{
  "items": [
    {
      "name": "MvPowerSeries.weightedOrder_mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.NoZeroDivisors",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] [NoZeroDivisors R] (w : σ → ℕ) (f g : MvPowerSeries σ R),\n  MvPowerSeries.weightedOrder w (f * g) = MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g"
    },
    {
      "name": "AddMonoidAlgebra.le_inf_support_mul",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {T : Type u_4} [inst : SemilatticeInf T] [inst_1 : OrderTop T] [inst_2 : Semiring R]\n  [inst_3 : Add A] [inst_4 : Add T] [AddLeftMono T] [AddRightMono T] {degt : A → T},\n  (∀ (a b : A), degt a + degt b ≤ degt (a + b)) →\n    ∀ (f g : AddMonoidAlgebra R A), f.support.inf degt + g.support.inf degt ≤ (f * g).support.inf degt"
    },
    {
      "name": "MvPolynomial.support_mul",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : DecidableEq σ] (p q : MvPolynomial σ R),\n  (p * q).support ⊆ p.support + q.support"
    },
    {
      "name": "MvPolynomial.IsWeightedHomogeneous.mul",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M]\n  {φ ψ : MvPolynomial σ R} {m n : M} {w : σ → M},\n  MvPolynomial.IsWeightedHomogeneous w φ m →\n    MvPolynomial.IsWeightedHomogeneous w ψ n → MvPolynomial.IsWeightedHomogeneous w (φ * ψ) (m + n)"
    },
    {
      "name": "Multiset.prod_min_le",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Multiset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [inst : CommMonoid α] [inst_1 : LinearOrder α] [IsOrderedMonoid α] {s : Multiset ι}\n  {f g : ι → α}, (Multiset.map (fun i => min (f i) (g i)) s).prod ≤ min (Multiset.map f s).prod (Multiset.map g s).prod"
    }
  ]
}
